      "rationale": "P010 supplies the trigger and required response; P009 identifies the testing context."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C014_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This explicit operational safeguard requires no unresolved empirical relation to license stopping when its condition holds."
    }
  },
  "rationale": "The claim directly applies the mapping's conditional safety rule. Assuming testing threatens scheduled exports, stopping is licensed within the stated operational scope.",
